<?php require 'config/database.php';$pageTitle='Job Seekers';$rows=$conn->query("SELECT s.seeker_id,s.phone,s.qualification,s.skills,u.name,u.email,a.application_id,a.status,a.candidate_response,j.title,j.company_name FROM job_seekers s JOIN users u ON u.user_id=s.seeker_id LEFT JOIN applications a ON a.seeker_id=s.seeker_id LEFT JOIN jobs j ON j.job_id=a.job_id ORDER BY s.seeker_id DESC,a.application_id DESC");include 'includes/header.php';?>
<section class="seeker-status-hero"><small>CANDIDATE PROGRESS BOARD</small><h1>Job Seeker Status</h1><p>Every candidate can see the current recruitment decision using the Application ID.</p></section><section class="card"><h1>JOB_SEEKER</h1><div class="table-wrap"><table><tr><th>Application ID</th><th>Candidate</th><th>Applied Job</th><th>Company</th><th>Qualification</th><th>Recruitment Status</th><th>Next Step</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?php if($r['application_id']):?><strong>APP-<?=str_pad($r['application_id'],6,'0',STR_PAD_LEFT)?></strong><?php else:?>—<?php endif;?></td><td><?=htmlspecialchars($r['name'])?><small class="table-sub"><?=htmlspecialchars($r['phone'])?></small></td><td><?=htmlspecialchars($r['title']??'Not applied')?></td><td><?=htmlspecialchars($r['company_name']??'—')?></td><td><?=htmlspecialchars($r['qualification'])?></td><td><?php if($r['application_id']):?><span class="status <?=strtolower($r['status'])?>"><?=$r['status']==='Accepted'?'Selected':$r['status']?></span><?php else:?><span class="status pending">No Application</span><?php endif;?></td><td><?php if(!$r['application_id']):?><span class="waiting-text">No result</span><?php elseif($r['status']==='Accepted'&&$r['candidate_response']==='Accepted'):?><a class="mini-link" href="appointment_letter.php?id=<?=$r['application_id']?>">Download Letter</a><?php elseif($r['status']==='Accepted'):?><a class="action-link" href="tracking.php?id=<?=$r['application_id']?>">Accept / Decline Job</a><?php else:?><a class="action-link" href="tracking.php?id=<?=$r['application_id']?>">View Status</a><?php endif;?></td></tr><?php endwhile;?></table></div></section><?php include 'includes/footer.php';?>
